        TruthOrDareItem(id: 110, isDare: true, spice: 3, text: LText(de: "Schick mir ein Foto, auf dem du mir einen Kuss zuwirfst.", en: "Send me a photo of you blowing me a kiss.")),
        TruthOrDareItem(id: 111, isDare: true, spice: 3, text: LText(de: "Nenn mir drei Dinge, die du an meinem Körper bewunderst — langsam und mit Blickkontakt.", en: "Tell me three things you admire about my body — slowly and with eye contact.")),
        TruthOrDareItem(id: 112, isDare: true, spice: 3, text: LText(de: "Frag mich: „Magst du eine Minute Schultermassage?“ — und warte auf mein Ja, bevor du anfängst und mir dabei erzählst, was du an mir liebst.", en: "Ask me: \"Would you like a one-minute shoulder rub?\" — and wait for my yes before you begin, telling me what you love about me as you go.")),
        TruthOrDareItem(id: 113, isDare: true, spice: 3, text: LText(de: "Frag mich: „Bereit für einen 10-Sekunden-Kuss?“ — und erst wenn ich Ja sage, leg los. Kichern ausdrücklich erlaubt.", en: "Ask me: \"Ready for a ten-second kiss?\" — and only once I say yes, go for it. Giggling absolutely allowed.")),
        TruthOrDareItem(id: 114, isDare: true, spice: 3, text: LText(de: "Schick mir eine Sprachnachricht mit deiner verführerischsten Stimme — Inhalt frei wählbar.", en: "Send me a voice note in your most seductive voice — content up to you.")),
        TruthOrDareItem(id: 115, isDare: true, spice: 3, text: LText(de: "Zieh ein Kleidungsstück aus, wenn es sich für dich gut anfühlt — Socken zählen voll.", en: "Take off one piece of clothing if that feels right to you — socks count fully.")),
        TruthOrDareItem(id: 116, isDare: true, spice: 3, text: LText(de: "Flüstere mir drei Orte zu, an denen du mich gern küssen würdest.", en: "Whisper three places you'd like to kiss me.")),
        TruthOrDareItem(id: 117, isDare: true, spice: 3, text: LText(de: "Zeig mir in 30 Sekunden, wie du mich verführen würdest — nur mit Blicken.", en: "Show me in 30 seconds how you'd seduce me — using only your eyes.")),
        TruthOrDareItem(id: 118, isDare: true, spice: 3, text: LText(de: "Frag mich, welche Küsse ich gerade mag — Nasenkuss, Schmetterlingskuss, ein richtiger? — und schenk mir genau die, zu denen ich Ja sage.", en: "Ask me which kisses I'm in the mood for — nose-to-nose, butterfly, a real one? — and give me exactly the ones I say yes to.")),
        TruthOrDareItem(id: 119, isDare: true, spice: 3, text: LText(de: "Beschreibe mir flüsternd dein perfektes romantisches Wochenende mit mir — und frag vorher: „Wange an Wange?“ Nur bei meinem Ja rücken wir zusammen.", en: "Whisper your perfect romantic weekend with me — but ask first: \"Cheek to cheek?\" Only my yes moves us closer.")),
        TruthOrDareItem(id: 120, isDare: true, spice: 3, text: LText(de: "Frag mich: „Darf ich dir etwas auf den Arm schreiben?“ — nach meinem Ja schreib mit dem Finger eine Liebesbotschaft und ich rate, was da steht.", en: "Ask me: \"May I write something on your arm?\" — after my yes, trace a love message with your finger and I'll guess what it says.")),
        TruthOrDareItem(id: 121, isDare: false, spice: 1, text: LText(de: "Welches unserer kleinen Rituale möchtest du niemals aufgeben?", en: "Which of our little rituals would you never want to give up?")),
        TruthOrDareItem(id: 122, isDare: false, spice: 1, text: LText(de: "Was fühlt sich in unserem Zuhause am meisten nach „uns“ an?", en: "What about our home feels the most like “us” to you?")),
        TruthOrDareItem(id: 123, isDare: false, spice: 2, text: LText(de: "Welche Nachricht von mir liest du manchmal heimlich nochmal?", en: "Which message from me do you secretly reread sometimes?")),
        TruthOrDareItem(id: 124, isDare: false, spice: 2, text: LText(de: "Bei welchem Anblick von mir musstest du zuletzt grinsen, ohne dass ich es gemerkt habe?", en: "What sight of me last made you grin without me noticing?")),
        TruthOrDareItem(id: 125, isDare: false, spice: 3, text: LText(de: "Welcher unserer Küsse geht dir bis heute nicht aus dem Kopf?", en: "Which of our kisses still lives rent-free in your head?")),
        TruthOrDareItem(id: 126, isDare: true, spice: 1, text: LText(de: "Beschreibe mich in genau fünf Wörtern — du hast 10 Sekunden!", en: "Describe me in exactly five words — you have 10 seconds!")),
        TruthOrDareItem(id: 127, isDare: true, spice: 1, text: LText(de: "Summ unser Lied, bis ich errate, welches es ist.", en: "Hum our song until I guess which one it is.")),
        TruthOrDareItem(id: 128, isDare: true, spice: 2, text: LText(de: "Schau mir 20 Sekunden in die Augen und sag danach deinen ersten Gedanken laut.", en: "Look into my eyes for 20 seconds, then say your first thought out loud.")),
        TruthOrDareItem(id: 129, isDare: true, spice: 2, text: LText(de: "Erfinde jetzt einen neuen Kosenamen für mich und benutze ihn den restlichen Abend.", en: "Invent a new pet name for me right now and use it for the rest of the evening.")),
        TruthOrDareItem(id: 130, isDare: true, spice: 3, text: LText(de: "Flüstere mir, wo du mich in einer Minute gern küssen würdest — und nur wenn ich laut Ja sage, halt dich daran.", en: "Whisper where you'd like to kiss me in one minute — and only if I say yes out loud, follow through.")),
        TruthOrDareItem(id: 131, isDare: false, spice: 1, text: LText(de: "Welche Angewohnheit hast du dir von mir abgeschaut, ohne es zu wollen?", en: "Which habit of mine have you picked up without meaning to?")),
        TruthOrDareItem(id: 132, isDare: false, spice: 1, text: LText(de: "Was war der Moment diese Woche, in dem du am liebsten sofort bei mir gewesen wärst?", en: "What moment this week made you wish you could be with me instantly?")),
        TruthOrDareItem(id: 133, isDare: false, spice: 2, text: LText(de: "Welches Geheimnis über deine Gefühle für mich hast du am längsten für dich behalten?", en: "Which secret about your feelings for me did you keep to yourself the longest?")),
        TruthOrDareItem(id: 134, isDare: false, spice: 2, text: LText(de: "Was denkst du als Erstes, wenn ich morgens verschlafen neben dir aufwache?", en: "What's the first thing you think when I wake up all sleepy next to you?")),
        TruthOrDareItem(id: 135, isDare: false, spice: 3, text: LText(de: "Welche Berührung von mir bringt dich jedes Mal aus dem Konzept?", en: "Which touch of mine throws you off every single time?")),
        TruthOrDareItem(id: 136, isDare: true, spice: 1, text: LText(de: "Stell mein Lieblingsemoji mit deinem ganzen Körper nach — ich muss es erraten.", en: "Act out my favorite emoji with your whole body — I have to guess it.")),
        TruthOrDareItem(id: 137, isDare: true, spice: 1, text: LText(de: "Sing die nächste Antwort, statt sie zu sprechen — Opernstimme erwünscht.", en: "Sing your next answer instead of speaking it — opera voice encouraged.")),
        TruthOrDareItem(id: 138, isDare: true, spice: 2, text: LText(de: "Schreib mir mit geschlossenen Augen eine Liebesnachricht und schick sie ab, ohne sie zu korrigieren.", en: "Type me a love note with your eyes closed and send it without fixing anything.")),
        TruthOrDareItem(id: 139, isDare: true, spice: 2, text: LText(de: "Erkläre mir mit ernster Stimme wie in einer Doku, warum ich unwiderstehlich bin.", en: "In a serious documentary-narrator voice, explain why I'm irresistible.")),
        TruthOrDareItem(id: 140, isDare: true, spice: 3, text: LText(de: "Wähle eine Stelle, die du gleich küssen möchtest — sag sie mir leise und warte, bis ich Ja sage.", en: "Pick a spot you'd like to kiss in a moment — tell me quietly and wait until I say yes.")),
        // Expansion (ids 141–160: 10 truths + 10 dares)
        TruthOrDareItem(id: 141, isDare: false, spice: 1, text: LText(de: "Welchen unserer Insider-Witze erklärst du niemandem — und warum ist er so gut?", en: "Which of our inside jokes would you never explain to anyone — and why is it so good?")),
        TruthOrDareItem(id: 142, isDare: false, spice: 1, text: LText(de: "Was tue ich, wenn ich denke, dass niemand hinschaut — und du findest es süß?", en: "What do I do when I think nobody's watching — that you secretly find cute?")),
        TruthOrDareItem(id: 143, isDare: false, spice: 1, text: LText(de: "Welchen Spitznamen hättest du mir fast gegeben, dich aber nicht getraut?", en: "Which nickname did you almost give me but never dared to?")),
        TruthOrDareItem(id: 144, isDare: false, spice: 1, text: LText(de: "Bei welchem Thema hörst du mir am liebsten zu, auch wenn du nichts verstehst?", en: "Which topic do you love hearing me talk about, even when you understand nothing?")),
        TruthOrDareItem(id: 145, isDare: false, spice: 2, text: LText(de: "Welche Nachricht von mir hast du am häufigsten wieder gelesen?", en: "Which message from me have you re-read the most?")),
        TruthOrDareItem(id: 146, isDare: false, spice: 2, text: LText(de: "Welche Nachricht von mir hast du schon heimlich einem Freund oder einer Freundin gezeigt?", en: "Which message of mine have you secretly shown a friend?")),
        TruthOrDareItem(id: 147, isDare: false, spice: 2, text: LText(de: "Welchen Moment mit mir würdest du gern in Zeitlupe wiederholen?", en: "Which moment with me would you replay in slow motion?")),
        TruthOrDareItem(id: 148, isDare: false, spice: 2, text: LText(de: "Was denkst du als Erstes, wenn mein Name auf deinem Display aufleuchtet?", en: "What's your first thought when my name lights up on your screen?")),
        TruthOrDareItem(id: 149, isDare: false, spice: 3, text: LText(de: "Welcher Gedanke über mich hat dich zuletzt rot werden lassen?", en: "Which thought about me last made you blush?")),
        TruthOrDareItem(id: 150, isDare: false, spice: 3, text: LText(de: "Was würdest du tun, wenn wir jetzt eine Stunde ganz ungestört wären?", en: "What would you do if we had one completely undisturbed hour right now?")),
        TruthOrDareItem(id: 151, isDare: true, spice: 1, text: LText(de: "Baue in die nächsten drei Sätze unauffällig je ein Kompliment an mich ein.", en: "Sneak one compliment about me into each of your next three sentences.")),
        TruthOrDareItem(id: 152, isDare: true, spice: 1, text: LText(de: "Stell dein Hintergrundbild für heute auf das albernste Foto von uns.", en: "Set your wallpaper to the silliest photo of us for the rest of the day.")),
        TruthOrDareItem(id: 153, isDare: true, spice: 1, text: LText(de: "Imitiere 30 Sekunden lang, wie ich morgens aufwache — liebevoll, versteht sich.", en: "Do a 30-second impression of how I wake up in the morning — lovingly, of course.")),
        TruthOrDareItem(id: 154, isDare: true, spice: 1, text: LText(de: "Schick mir eine Sprachnachricht, in der du unser Kennenlernen wie ein Märchen erzählst.", en: "Send me a voice note telling the story of how we met as a fairy tale.")),
        TruthOrDareItem(id: 155, isDare: true, spice: 2, text: LText(de: "Flüstere mir drei Dinge ins Ohr, die du an mir liebst — ohne zu lachen.", en: "Whisper three things you love about me in my ear — without laughing.")),
        TruthOrDareItem(id: 156, isDare: true, spice: 2, text: LText(de: "Tanzt zusammen einen langsamen Song — du führst, egal wie ungeübt.", en: "Slow-dance to one song together — you lead, no matter how rusty.")),
        TruthOrDareItem(id: 157, isDare: true, spice: 2, text: LText(de: "Schreib mir jetzt die Nachricht, die du mir nach unserem ersten Date gern geschickt hättest.", en: "Text me the message you wish you'd sent after our first date.")),
        TruthOrDareItem(id: 158, isDare: true, spice: 2, text: LText(de: "Sieh mir 60 Sekunden in die Augen, ohne zu reden — danach sagt jeder einen Satz.", en: "Hold eye contact with me for 60 seconds, no talking — then each of you says one sentence.")),
        TruthOrDareItem(id: 159, isDare: true, spice: 3, text: LText(de: "Beschreibe unseren nächsten perfekten Kuss — und wenn ich Ja sage, probieren wir ihn gleich aus.", en: "Describe our next perfect kiss — and if I say yes, we'll try it out right away.")),
        TruthOrDareItem(id: 160, isDare: true, spice: 3, text: LText(de: "Biete mir eine 60-Sekunden-Massage an, Stelle deiner Wahl — Handy weg, volle Aufmerksamkeit.", en: "Offer me a 60-second massage, spot of your choice — phone away, full attention."))
    ]
